const makeMines = () => { const bombs = new Set(); while (bombs.size < 10) bombs.add(Math.floor(Math.random()*81)); return Array.from({length:81},(_,i)=>({bomb:bombs.has(i),open:false,flag:false,n:[-10,-9,-8,-1,1,8,9,10].filter(d=>{const j=i+d;return j>=0&&j<81&&Math.abs((j%9)-(i%9))<=1&&bombs.has(j)}).length})); };
const initChess = () => ['♜','♞','♝','♛','♚','♝','♞','♜',...'♟'.repeat(8),...Array(32).fill(''),...'♙'.repeat(8),'♖','♘','♗','♕','♔','♗','♘','♖'].map((p,i)=>({p,side:i<16?'black':i>=48?'white':null}));
const initDraughts = () => Array.from({length:64},(_,i)=>{const r=Math.floor(i/8),c=i%8;return {p:(r+c)%2&&r<3?'●':(r+c)%2&&r>4?'○':'',king:false};});
